201	// One claimed item, from validation through to a terminal state (or a hand-off).
202	async function executeItem({
203	  api, gh, repo, root, config, schedule, byId, item, executorId,
204	  now, collectSignalsFor, runTaskPrework, invokeAgent, log,
205	}) {
206	  const parsed = parseWorkItemTitle(item.title);
207	  const { taskPath } = parseWorkItemBody(item.body);
208	  const id = parsed ? `${parsed.pack}/${parsed.task}` : null;
209	  const task = id ? byId.get(id) : null;
210	
211	  // --- validate in code, before anything trusts the issue ------------------
212	  if (!parsed || !taskPath) {
213	    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
214	      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.');
215	    return 'needs-human';
216	  }
217	  if (!task) {
218	    await close(api, gh, repo, item.number, EXECUTING, OUTCOME_OBSOLETE, 'not_planned',
219	      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`);
220	    return 'obsolete';
221	  }
222	  if (task.taskPath !== taskPath) {
223	    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
224	      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`);
225	    return 'needs-human';
226	  }
227	
228	  // --- the single precondition evaluation (DESIGN §6.4) --------------------
229	  const at = now();
230	  const signals = await collectSignalsFor(task, at);
231	  let verdict;
232	  try {
233	    verdict = task.decl.precondition(signals, config.packConfig?.[task.pack] ?? {}) ?? {};
234	  } catch (e) {
235	    verdict = { run: false, reason: `precondition threw: ${e.message}` };
236	  }
237	  if (verdict.run !== true) {
238	    const plan = noGoPlan(item, task, schedule, at, verdict.reason || 'no work');
239	    if (plan.kind === 'close') {
240	      await close(api, gh, repo, item.number, EXECUTING, OUTCOME_OBSOLETE, 'not_planned',
241	        `The precondition declined and this item has no anchor to roll to: ${plan.reason}`);
242	      return 'obsolete';
243	    }
244	    // The roll writes no comment — the `Not-before` bump IS the record, and an
245	    // hourly task that stays quiet would otherwise fill its own timeline (§5).
246	    await gh(`/repos/${repo}/issues/${item.number}`, {
247	      method: 'PATCH',
248	      body: { body: rollBody(item.body, plan.until, plan.reason, at.toISOString()) },
249	    });
250	    await api.swapLabel(gh, repo, item.number, EXECUTING, BLOCKED);
251	    log(`- #${item.number} ${id}: rolled to ${plan.until} — ${plan.reason}`);
252	    return 'rolled';
253	  }
254	
255	  // --- prework (unchanged contract), then converge or hand off -------------
256	  if (task.decl.prework) {
257	    const result = await runTaskPrework(task, { item, context: verdict.context ?? [] });
258	    if (!result.ok) {
259	      await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
260	        `Prework failed: ${result.why}${result.detail ? `\n\n\`\`\`\n${result.detail}\n\`\`\`` : ''}`);
261	      return 'needs-human';
262	    }
263	    if (result.missingSecrets?.length) {
264	      await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
265	        `This task declares repo Actions secrets that are not configured: ${result.missingSecrets.join(', ')}. Set them in repo settings and re-queue this item (remove \`needs-human\`, add \`task:ready\`).`);
266	      return 'needs-human';
267	    }
268	    if (!result.agentRequested) {
269	      const outcome = result.delivered?.length ? OUTCOME_DELIVERED : OUTCOME_DONE;
270	      await close(api, gh, repo, item.number, EXECUTING, outcome, 'completed',
271	        result.delivered?.length
272	          ? `Prework did this run's work and left a live artifact:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
273	          : 'Prework did this run\'s work; no agent was needed.');
274	      return outcome;
275	    }
276	    return handOff({ api, gh, repo, item, task, id, verdict, result, executorId, invokeAgent, config, log });
277	  }
278	
279	  // An agentless task with no prework does nothing (the contract forbids it).
280	  if (task.decl.agent_model === 'none') {
281	    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
282	      'This task is agentless but declares no prework, so there is nothing to run — a contract-forbidden shape that reached the queue.');
283	    return 'needs-human';
284	  }
285	  return handOff({ api, gh, repo, item, task, id, verdict, result: {}, executorId, invokeAgent, config, log });
286	}
287	
288	// The roll's body edit: stamp the next anchor and keep the last reason where an
289	// operator reads it. The reason REPLACES the previous one — the item is a status
290	// line, not a log; its timeline carries the history.
291	export function rollBody(body, until, reason, at) {
292	  const stamped = withNotBefore(body, until);
293	  return withSection(stamped, 'Last verdict', [
294	    `${at} — the precondition declined: ${reason}`,
295	    `Asked again at ${until}.`,
296	  ]);
297	}
298	
299	// Hand off to an agent session (DESIGN §6.6). ONE call per item, ever — which is
300	// what lets this be as short as it is. The nonce goes on the item before the call
301	// and travels in the payload, so the session can prove the fire it arrived on is
302	// the hand-off this item recorded and stop if it is not.
303	async function handOff({ api, gh, repo, item, task, id, verdict, result, executorId, invokeAgent, config, log }) {
304	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
305	  let body = item.body;
306	  if (verdict.context?.length) body = withSection(body, 'Context', verdict.context);
307	  if (result.delivered?.length) body = withSection(body, 'Delivered by prework', result.delivered);
308	  if (result.reason) body = withSection(body, 'Why the agent is here', [result.reason]);
309	  await gh(`/repos/${repo}/issues/${item.number}`, { method: 'PATCH', body: { body } });
310	
311	  await api.swapLabel(gh, repo, item.number, EXECUTING, AGENT);
312	  await api.comment(gh, repo, item.number,
313	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);
314	
315	  const invocation = await invokeAgent({ task, item, nonce, config });
316	  if (invocation.ok) {
317	    await api.comment(gh, repo, item.number,
318	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
319	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
320	    return 'agent';
321	  }
322	  if (invocation.answered) {
323	    // The endpoint refused, so no session exists and none will: a token, a URL or
324	    // a routine is wrong, and every future pick would be refused the same way.
325	    await converge(api, gh, repo, item.number, AGENT, NEEDS_HUMAN,
326	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (remove \`${NEEDS_HUMAN}\`, add \`${READY}\`).`);
327	    return 'needs-human';
328	  }
329	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
330	  // may have started a session. Re-queueing here is what would put two sessions on
331	  // one item, and converging to triage would kill a run that is very possibly
